"""REST over urllib for the gates' external services (EVOL-080; extracted from the EVOL-079 Jira transport).

call(service, site_hint, auth_hint, method, url, headers, body=None) → (status, parsed JSON | None).
  - A redirect is answered, never followed: the credential is sent to the configured site only.
  - A 429 waits its Retry-After once (an ASCII decimal, at most 60 s; anything else waits 5 s); a second 429 is a fault.
  - `Unreachable` (a GateFault) is the transport class: no connection, a body that is not JSON, a 5xx, a repeated 429,
    401/403. Every other answer (a redirect, a 4xx) is a plain GateFault naming the status and the server's reason.
  - No message carries the URL's query or a header value — the credential never reaches a message.
"""
from __future__ import annotations

import json
import time
import urllib.error
import urllib.request

from .common import GateFault, clean


class Unreachable(GateFault):
    """The service could not answer: the transport, the server or the credential — an infrastructure fault."""


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


_OPEN = urllib.request.build_opener(_NoRedirect).open


def ascii_int(v) -> bool:
    """An ASCII decimal: `str.isdigit` also takes `²`, which `int` refuses."""
    t = str(v if v is not None else "")
    return t.isascii() and t.isdigit()


def _reason(e: urllib.error.HTTPError) -> str:
    try:
        msg = json.loads(e.read().decode("utf-8") or "{}")
    except (ValueError, OSError, AttributeError):
        return ""
    if not isinstance(msg, dict):
        return ""
    parts = [*(msg.get("errorMessages") or []), *(f"{k}: {v}" for k, v in (msg.get("errors") or {}).items() if isinstance(msg.get("errors"), dict))]
    if not parts and isinstance(msg.get("message"), str):
        parts = [msg["message"]]
    return "; ".join(str(p) for p in parts)


def call(service: str, site_hint: str, auth_hint: str, method: str, url: str, headers: dict, body=None):
    data = json.dumps(body).encode("utf-8") if body is not None else None
    req = urllib.request.Request(url, data=data, method=method, headers={"Accept": "application/json", "User-Agent": "myrmion-gate",
                                                                        **({"Content-Type": "application/json"} if data else {}), **headers})
    short = url.split("?")[0]
    for attempt in (1, 2):
        try:
            with _OPEN(req, timeout=30) as r:
                raw = r.read().decode("utf-8")
                return r.status, (json.loads(raw) if raw.strip() else None)
        except urllib.error.HTTPError as e:
            with e:   # an HTTPError holds the response open: closed on every path
                if e.code == 429:
                    if attempt == 2:
                        raise Unreachable(f"{service} kept rate-limiting {short} — re-run later") from None
                    ra = e.headers.get("Retry-After") or "5"
                    time.sleep(min(int(ra) if ascii_int(ra) else 5, 60))
                    continue
                if 300 <= e.code < 400:
                    raise GateFault(f"{service} redirected {short} ({e.code}) — the token is never sent on: {site_hint}") from None
                if e.code in (401, 403):
                    raise Unreachable(f"{service} refused {short} ({e.code}) — {auth_hint}") from None
                why = _reason(e)
                cls = Unreachable if e.code >= 500 else GateFault
                raise cls(f"{service} answered {e.code} for {short}" + (f" ({clean(why, 300)})" if why else "")) from None
        except (urllib.error.URLError, OSError, ValueError) as e:
            raise Unreachable(f"{service} could not be reached at {short} ({clean(e, 200)}) — transient: re-run; a fault, never a pass") from None
